    fileprivate static let handleMap = UniffiHandleMap<HostTransport>()

    typealias FfiType = UInt64
    typealias SwiftType = HostTransport

    public static func lift(_ handle: UInt64) throws -> HostTransport {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return HostTransportImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
